import{_ as e,o as a,c as i,ag as t}from"./chunks/framework.CAfGEm1x.js";const c=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),n={name:"getting-started.md"};function l(o,s,d,h,r,p){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="choose-an-installation-method" tabindex="-1">Choose an installation method <a class="header-anchor" href="#choose-an-installation-method" aria-label="Permalink to &quot;Choose an installation method&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Best for</th><th>Availability</th></tr></thead><tbody><tr><td><a href="#build-and-run-from-source">Clone or download the source</a></td><td>Building locally or contributing</td><td>Available</td></tr><tr><td><a href="#download-a-release-executable">Download a release executable</a></td><td>Running on macOS without installing Bun</td><td>Available for Apple Silicon and Intel Macs</td></tr><tr><td><a href="#homebrew-coming-soon">Install with Homebrew</a></td><td>Package-manager installation and updates</td><td>Coming soon</td></tr></tbody></table><h2 id="build-and-run-from-source" tabindex="-1">Build and run from source <a class="header-anchor" href="#build-and-run-from-source" aria-label="Permalink to &quot;Build and run from source&quot;">​</a></h2><p>Install <a href="https://bun.sh/docs/installation" target="_blank" rel="noreferrer">Bun</a> 1.2 or newer. Get the code in either of these ways:</p><ul><li><strong>Clone the repository:</strong></li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/vikz91/kundol.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kundol</span></span></code></pre></div><ul><li><strong>Download the code:</strong> download the <a href="https://github.com/vikz91/kundol/archive/refs/heads/main.zip" target="_blank" rel="noreferrer">source ZIP</a>, extract it, and open a terminal in the extracted <code>kundol-main</code> directory.</li></ul><p>From the repository directory, build and install the CLI:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register:cli</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.local/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> available</span></span></code></pre></div><p>Every <code>register:cli</code> run reinstalls dependencies, builds a fresh universal macOS executable, and overwrites <code>~/.local/bin/kundol</code>. The installed command runs independently of Bun and this checkout. Run <code>bun run register:cli</code> again after updating the source to rebuild and replace the installed version.</p><p>Building requires macOS and Apple&#39;s Command Line Tools (<code>lipo</code> and <code>codesign</code>). The executable supports Apple Silicon and Intel Macs. The source on <code>main</code> may be newer than the latest release.</p><p>The installer prints PATH guidance but does not edit shell files. The <code>export</code> above applies to the current shell; add that same line to <code>~/.zshrc</code> (or your shell&#39;s configuration file) to keep it in future sessions.</p><p>For development, you can run directly from the checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>To build an executable without installing it, run <code>bun run build:release --outfile dist/kundol</code>, then <code>./dist/kundol --help</code>.</p><h2 id="download-a-release-executable" tabindex="-1">Download a release executable <a class="header-anchor" href="#download-a-release-executable" aria-label="Permalink to &quot;Download a release executable&quot;">​</a></h2><p>Open the <a href="https://github.com/vikz91/kundol/releases/latest" target="_blank" rel="noreferrer">latest release</a> and download <strong><code>kundol-macos-universal</code></strong> from <strong>Assets</strong>. This single file supports Apple Silicon and Intel Macs; Bun is bundled, so you do not need to install it separately.</p><p>Alternatively, download it from your terminal into a directory of your choice:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --location</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://github.com/vikz91/kundol/releases/latest/download/kundol-macos-universal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kundol</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kundol</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./kundol</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./kundol</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> available</span></span></code></pre></div><p>If you downloaded through your browser, rename <code>kundol-macos-universal</code> to <code>kundol</code> and run the commands starting with <code>chmod</code> from that download directory. The executable has an ad hoc signature, not Apple notarization, so macOS may show a download warning. Published executables are currently macOS-only.</p><h2 id="homebrew-coming-soon" tabindex="-1">Homebrew coming soon <a class="header-anchor" href="#homebrew-coming-soon" aria-label="Permalink to &quot;Homebrew coming soon&quot;">​</a></h2><p>Homebrew installation is planned but is not available yet. Use the source or release-executable option above for now. The installation command will be added here when the tap and formula are ready.</p><h2 id="run-manual-examples" tabindex="-1">Run manual examples <a class="header-anchor" href="#run-manual-examples" aria-label="Permalink to &quot;Run manual examples&quot;">​</a></h2><p>The source installer makes <code>kundol</code> available once <code>~/.local/bin</code> is on your <code>PATH</code>. For other setups, substitute the command for your chosen method:</p><table tabindex="0"><thead><tr><th>Your setup</th><th>Example</th></tr></thead><tbody><tr><td>Manually built from source, in the repository directory</td><td><code>./dist/kundol tools available</code></td></tr><tr><td>Downloaded release, in its download directory</td><td><code>./kundol tools available</code></td></tr><tr><td>Running source through Bun, in the repository directory</td><td><code>bun run dev -- tools available</code></td></tr></tbody></table><p>Generated-file deletion requires <code>/usr/bin/python3</code> with descriptor-based filesystem support. Owner-tool cache rules also require their corresponding tool, such as npm or pnpm.</p><h2 id="try-disposable-projects" tabindex="-1">Try disposable projects <a class="header-anchor" href="#try-disposable-projects" aria-label="Permalink to &quot;Try disposable projects&quot;">​</a></h2><p>The sandbox requires a source checkout or extracted source ZIP, even if you normally use the release executable. With Docker running, build it from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kundol-demo:local</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cap-drop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --security-opt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no-new-privileges</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kundol-demo:local</span></span></code></pre></div><p>Inside the container:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> projects</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sandbox/projects</span></span></code></pre></div><ul><li>Read the printed targets, actions, and safety tiers.</li><li>Press Enter with a blank answer to cancel, enter <code>y</code> for safe suggestions, or enter displayed target numbers for explicit selection.</li><li>Exit the container when finished. Starting a new container restores the disposable fixtures.</li></ul><p>The example mounts no host projects or Docker socket. Building it leaves a Docker image on your machine.</p><h2 id="choose-a-scope" tabindex="-1">Choose a scope <a class="header-anchor" href="#choose-a-scope" aria-label="Permalink to &quot;Choose a scope&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Command</th></tr></thead><tbody><tr><td>Review owner-tool caches</td><td><code>kundol optimise storage</code></td></tr><tr><td>Review generated files under a workdir</td><td><code>kundol optimise projects ~/Projects</code></td></tr><tr><td>Use the equivalent repos route</td><td><code>kundol optimise repos ~/Projects</code></td></tr><tr><td>Inspect a named Docker context</td><td><code>kundol optimise docker my-context</code></td></tr><tr><td>Combine all scopes in one plan</td><td><code>kundol optimise all --workdir ~/Projects --docker-context my-context</code></td></tr></tbody></table><p>Replace example paths and context names with your own. <code>repos</code> does not require Git. Docker currently has no published resource cleanup rule; beta opt-in adds protected network and volume inventory only.</p><h2 id="reuse-your-scopes" tabindex="-1">Reuse your scopes <a class="header-anchor" href="#reuse-your-scopes" aria-label="Permalink to &quot;Reuse your scopes&quot;">​</a></h2><p>The first valid project directory is saved as an absolute canonical path in <code>~/.kundol/kundol.db</code>. Subsequent project or all-scope runs can omit it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> projects</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Projects</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> projects</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos</span></span></code></pre></div><p>For the first Docker or all-scope run, omit the context to discover installed Docker contexts. A sole context is selected automatically; if several exist, choose one from the numbered prompt. The context is saved only after its daemon identity validates. Later runs reuse it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span></span></code></pre></div><p>Once defaults exist, explicit paths and contexts override them for that run only. To replace a default deliberately:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> projects</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --save-defaults</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-context</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --save-defaults</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --docker-context</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-context</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --save-defaults</span></span></code></pre></div><p>Saved defaults are validated each run. A missing directory or unavailable Docker context fails clearly; Kundol does not silently select another. No installed/reachable Docker context means the Docker command fails before scanning and saves no Docker default. For non-interactive runs with several contexts and no default, supply <code>--docker-context</code> to <code>all</code> or the context argument to <code>docker</code>; <code>-f</code> does not choose a context.</p><p>Storage and project commands do not require Docker. Help and catalogue commands remain read-only.</p><h2 id="find-supported-tools" tabindex="-1">Find supported tools <a class="header-anchor" href="#find-supported-tools" aria-label="Permalink to &quot;Find supported tools&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> available</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;pnpm&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kundol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> beta</span></span></code></pre></div><p>Catalogue commands do not run cleanup. Continue with <a href="./safety.html">safety and selection</a>, the <a href="./reference/cli.html">command reference</a>, or the <a href="./reference/rules.html">rule catalogue</a>.</p>`,49)])])}const u=e(n,[["render",l]]);export{c as __pageData,u as default};
